func manifestFileOutputFor(path string) (*manifestFileOutput, error) {
        h, b, err := fileDigest(path)
        if err != nil {
                return nil, err
        }
        return &manifestFileOutput{
                Path:        filepath.Base(path),
                SHA256:      h,
                SHA256Short: sha256Short(h),
                Bytes:       b,
        }, nil
}

